  public static string Use(ItemKind k){if(PackLayouts338.IsNew(k))return PackLayouts338.Description(k);if(AmmoCrafting328.IsComponent(k))return AmmoCrafting328.Description(k);if(RetiredMedicine321.IsRetired(k))return "旧版血包已退出使用，生命改为脱战后自动恢复。";if(IsArmor(k))return ArmorLoadout320.Description(k);if(ConsumableRules.IsRepair(k))return $"总维修点{RepairKit320.Capacity(k):0}，单次基础上限{ConsumableRules.RepairBase(k)}，使用4秒，只扣实际用掉的点数，余量保留、耗尽消失；同/高品质100%，低一级80%，受击中断不消耗。每包独立占1格。";if(KeyCase314.IsCase(k))return "占1格，内部2×2共4格，仅收纳钥匙。双击或右键打开，可拖入/取出钥匙。可放安全箱，包内钥匙也受保护并能直接开锁。";if(ModRules30.IsMod(k))return ModRules30.Get(k).Description;if(BlueWeapons30.IsNew(k))return BlueWeapons30.Description(k);if(KeyRules2760.IsKey(k))return KeyRules2760.Description(k);if(FormalCollectibles2749.IsNew(k))return FormalCollectibles2749.Description(k);if(WeaponRules279.IsWeapon(k)){var p=WeaponRules279.Get(k);return $"{GradeName(k)}{p.Name}：{p.CaliberLabel}；{(p.Automatic?"自动射击":"半自动／每次按键一发")}；伤害{p.Damage}、穿甲{p.Penetration}，弹匣{p.MagazineSize}发，换弹{p.ReloadSeconds:0.#}秒；最大弹程{p.Range:0.#}米；移动稳定性{p.MovementStability}。";}if(AmmoRules270.IsAmmo(k))return (WeaponRules279.AmmoCaliber(k)==AmmoCaliber279.NineMM?"MP5／短剑使用的9×19弹药；":"AK／SKS使用的7.62×39弹药；")+"攻击等级"+(Grade(k)+1)+"，破甲和生命减伤均按弹药品质计算；随身100发/格、仓库300发/格。R调用胸挂当前弹种；右键使用另一弹种会先卸回旧弹，再换弹。";if(CollectibleData260.IsNew(k))return CollectibleData260.Description(k);if((int)k>=32)return CollectionExpansion.Description(k);if(k==ItemKind.SecretArchive)return "极稀有红色收集品，保险箱或容器的额外红品抽奖有机会获得；固定售价20000金币。";if(IsRig(k)||IsPack(k)){var c=Container(new ItemStack(k,1),IsRig(k));return $"装备后提供 {c.Rows}×{c.Columns} 格；更换时保留内容，空间不足无法更换。";}switch(k){case ItemKind.HarborCoin:return "港口发行的旧纪念币；收藏品，可在仓库出售换取金币。";case ItemKind.BronzeStatuette:return "保存较好的旧铜船锚雕像；收藏品，可在仓库出售换取金币。";case ItemKind.Helmet:case ItemKind.BlueHelmet:case ItemKind.BlueArmor:case ItemKind.Armor:return "护甲未破时先扣护甲，破甲该发不伤血；归零后仍保留防具品质；破甲与生命阶段均按弹药品质对比防具品质减伤。";case ItemKind.Biomass:return "3份兑换1份医用材料";case ItemKind.Hide:return "2份兑换3份布料";case ItemKind.Chitin:return "2份兑换1件精密工具";case ItemKind.Scrap:return "制作弹药、步枪；认证材料可升级营地";case ItemKind.GunParts:return "制作AK；认证材料可升级工作台";case ItemKind.Circuit:return "兑换火药；认证材料用于工作台升级";case ItemKind.Cola:return "生活收藏品，可出售或用于后勤合作任务。";case ItemKind.Powder:return "制作弹药；认证材料可升级营地";case ItemKind.Cloth:return "制作简易或标准甲包的织物材料。";case ItemKind.Medical:return "医疗收藏品，可用于医疗合作任务和标准甲包制作。";case ItemKind.Tools:return "兑换枪械零件；用于工作台二级升级";case ItemKind.Intel:return "兑换AK；用于工作台二级升级";case ItemKind.AK:return $"绿色AK：最大弹程{WeaponRules279.AK.Range:0.#}米；高后坐、低精度，移动稳定性{WeaponHandling277.AkMovementStability}；连射上抬，向下压枪或短点射。基础伤害{WeaponRules270.Damage(k):0.#}、穿甲量{WeaponRules270.Penetration(k):0.#}；支持绿色一级/蓝色二级7.62弹药。";case ItemKind.Ammo:return "用于AK装填；局内每格最多100发，仓库每格最多300发；R只调用胸挂弹药";default:return "可在营地查看用途或出售。";}}
